  if (b < 0) {
    close(a);
    return -1;
  }
  char x[16384];
  for (;;) {
    ssize_t n = read(a, x, sizeof x);
    if (n < 0 && errno == EINTR)
      continue;
    if (n < 0) {
      close(a);
      close(b);
      return -1;
    }
    if (!n)
      break;
    if (wrall(b, x, (size_t)n)) {
      close(a);
      close(b);
      return -1;
    }
  }
